import { access, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import * as path from 'pathe';
import {
	deriveCorpusTransactionState,
	verifyWitnessAngularSuperProductivityEvidence,
	witnessAngularSuperProductivityAggregateMember,
	WITNESS_ANGULAR_SUPER_PRODUCTIVITY_RECEIPT_PATH,
} from '../../../core/src/index.ts';

const root = path.resolve(import.meta.dirname, '../../../..');
const aggregatePath = path.join(root, 'evidence/runs/aggregate.json');

/** Every state in which the SuperProductivity member is already published. */
const APPENDED_KINDS = new Set(['angular-super-productivity-browser-proof']);

function record(value: unknown, label: string): Record<string, unknown> {
	if (!value || typeof value !== 'object' || Array.isArray(value))
		throw new Error(`Angular Super Productivity aggregate ${label} must be an object`);
	return value as Record<string, unknown>;
}

async function exists(file: string): Promise<boolean> {
	try {
		await access(file);
		return true;
	} catch {
		return false;
	}
}

/**
 * The single SuperProductivity member is derived from the published evidence,
 * never authored by hand: verifying the browser proof re-hashes the two
 * build-lane receipts it seals, checks each receipt's own byte-identity claim
 * against the binding, and returns the Witness receipt's canonical digest, which
 * is the only digest the member carries.
 *
 * The lane appends one member rather than a pair: its two build-lane receipts
 * are sealed inside the Witness receipt by both canonical digest and exact
 * bytes, so a second aggregate row would restate a binding that already exists.
 */
export async function angularSuperProductivityAggregateMembers(rootDir = root): Promise<{
	witness: ReturnType<typeof witnessAngularSuperProductivityAggregateMember>;
}> {
	const verified = await verifyWitnessAngularSuperProductivityEvidence(rootDir);
	return { witness: witnessAngularSuperProductivityAggregateMember(verified.digest) };
}

function superProductivityPaths(fixtures: Array<Record<string, unknown>>): string[] {
	return fixtures
		.map((fixture) => fixture.receipt)
		.filter(
			(value): value is string =>
				value === WITNESS_ANGULAR_SUPER_PRODUCTIVITY_RECEIPT_PATH,
		);
}

/**
 * Appends the SuperProductivity member to the canonical aggregate and refuses
 * anything other than the exact TinyTranslator browser-proof predecessor state
 * or the exact already-appended SuperProductivity state. The append is atomic:
 * the composed aggregate is staged, re-derived, and only then renamed into
 * place.
 */
export async function appendAngularSuperProductivityAggregateMembers(rootDir = root): Promise<{
	kind: string;
	receipts: number;
	appended: boolean;
}> {
	const target = path.join(rootDir, 'evidence/runs/aggregate.json');
	const aggregate = record(JSON.parse(await readFile(target, 'utf8')), 'document');
	if (
		aggregate.schemaVersion !== 'versionless.aggregate.v1' ||
		!Array.isArray(aggregate.fixtures) ||
		!Array.isArray(aggregate.unsupported) ||
		aggregate.unsupported.length !== 0
	)
		throw new Error('Angular Super Productivity aggregate shape differs');
	const fixtures = aggregate.fixtures.map((item) => record(item, 'member'));
	const members = await angularSuperProductivityAggregateMembers(rootDir);
	if (superProductivityPaths(fixtures).length === 1) {
		const state = deriveCorpusTransactionState(fixtures);
		if (!APPENDED_KINDS.has(state.kind))
			throw new Error(
				'Angular Super Productivity aggregate membership is already inconsistent',
			);
		return { kind: state.kind, receipts: state.receipts, appended: false };
	}
	if (deriveCorpusTransactionState(fixtures).kind !== 'angular-tiny-translator-browser-proof')
		throw new Error(
			'Angular Super Productivity append requires the TinyTranslator browser-proof predecessor',
		);
	const composed = { ...aggregate, fixtures: [...fixtures, members.witness] };
	const state = deriveCorpusTransactionState(composed.fixtures);
	if (
		state.kind !== 'angular-super-productivity-browser-proof' ||
		state.receipts !== composed.fixtures.length
	)
		throw new Error('Angular Super Productivity append does not derive the browser-proof state');
	const staged = `${target}.t006b.tmp`;
	if (await exists(staged))
		throw new Error('Angular Super Productivity aggregate staging residue exists');
	try {
		await writeFile(staged, `${JSON.stringify(composed, null, 2)}\n`, { flag: 'wx' });
		const restaged = record(JSON.parse(await readFile(staged, 'utf8')), 'staged document');
		if (!Array.isArray(restaged.fixtures))
			throw new Error('Angular Super Productivity staging differs');
		const restagedState = deriveCorpusTransactionState(
			restaged.fixtures.map((item) => record(item, 'staged member')),
		);
		if (restagedState.kind !== 'angular-super-productivity-browser-proof')
			throw new Error('Angular Super Productivity staged aggregate does not re-derive');
		await rename(staged, target);
	} catch (error) {
		await unlink(staged).catch(() => undefined);
		throw error;
	}
	return { kind: state.kind, receipts: state.receipts, appended: true };
}

export async function main(args = process.argv.slice(2)): Promise<void> {
	if (args.length !== 1)
		throw new Error('Angular Super Productivity aggregate append requires one mode');
	const result =
		args[0] === '--append'
			? await appendAngularSuperProductivityAggregateMembers()
			: args[0] === '--verify-only'
				? await (async () => {
						const aggregate = record(
							JSON.parse(await readFile(aggregatePath, 'utf8')),
							'document',
						);
						if (!Array.isArray(aggregate.fixtures))
							throw new Error('Angular Super Productivity aggregate shape differs');
						const state = deriveCorpusTransactionState(
							aggregate.fixtures.map((item) => record(item, 'member')),
						);
						if (!APPENDED_KINDS.has(state.kind))
							throw new Error('Angular Super Productivity aggregate membership is absent');
						return { kind: state.kind, receipts: state.receipts, appended: false };
					})()
				: (() => {
						throw new Error('Angular Super Productivity aggregate append mode differs');
					})();
	process.stdout.write(`${JSON.stringify({ result: 'pass', ...result })}\n`);
}

if (process.argv[1]?.endsWith('angular-super-productivity-aggregate-append.ts'))
	main().catch((error: unknown) => {
